  @state RESERVE_ROWS = 0.3  @ 41   -- bottom breathing left clear below the last row (status band / modal edge)
  @state ANCHOR_HALO = 6  @ 42   -- px; matches curveEditor HIT_PX so the hit-rect covers anchors on the rect edge
